// Service worker for Lighthouse Hunter.
// Generated by tools/build.mjs - edit src/sw.template.js instead.
//
// Everything the game needs is precached on install, so it opens instantly and
// plays with no connection. The version changes whenever any published file
// changes, which drops the old cache.
const VERSION = "618ed13b";
const CACHE = 'lighthouse-' + VERSION;
const FILES = [
  "./",
  "index.html",
  "css/game.css?v=da649ceb",
  "js/game.js?v=247404a4",
  "apple-touch-icon.png",
  "favicon.png",
  "favicon.svg",
  "icon-192.png",
  "icon-512.png",
  "manifest.webmanifest",
  "og.jpg",
  "art/bat1.webp",
  "art/beach.webp",
  "art/boar1.webp",
  "art/boss1.webp",
  "art/bridge.webp",
  "art/cave.webp",
  "art/crab1.webp",
  "art/ground_beach.webp",
  "art/ground_bridge.webp",
  "art/ground_cave.webp",
  "art/ground_lighthouse.webp",
  "art/hunter_idle.webp",
  "art/hunter_jump.webp",
  "art/hunter_run1.webp",
  "art/hunter_run2.webp",
  "art/hunter_run3.webp",
  "art/hunter_stab.webp",
  "art/jungle.webp",
  "art/lighthouse.webp",
  "art/panther1.webp",
  "art/panther2.webp",
  "art/snake1.webp"
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(FILES)).then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;                       // posts and the board go straight out
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;         // fonts and the leaderboard are not ours

  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => {
      if (hit) {
        // refresh in the background so the next visit is current
        event.waitUntil(
          fetch(req).then((res) => {
            if (res && res.ok) return caches.open(CACHE).then((c) => c.put(req, res.clone()));
          }).catch(() => {}),
        );
        return hit;
      }
      return fetch(req)
        .then((res) => {
          if (res && res.ok) {
            const copy = res.clone();
            caches.open(CACHE).then((c) => c.put(req, copy));
          }
          return res;
        })
        .catch(() => (req.mode === 'navigate' ? caches.match('index.html') : Response.error()));
    }),
  );
});
